import{_ as t,o,c as a,a2 as n}from"./chunks/framework.Ce1WstT_.js";const g=JSON.parse('{"title":"12. Frontend Application","description":"","frontmatter":{},"headers":[],"relativePath":"development/frontend.md","filePath":"development/frontend.md"}'),i={name:"development/frontend.md"};function r(c,e,s,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_12-frontend-application" tabindex="-1">12. Frontend Application <a class="header-anchor" href="#_12-frontend-application" aria-label="Permalink to &quot;12. Frontend Application&quot;">​</a></h1><p>The presentation tier is a React 18 Single Page Application compiled with Vite.</p><h2 id="architecture-highlights" tabindex="-1">Architecture Highlights <a class="header-anchor" href="#architecture-highlights" aria-label="Permalink to &quot;Architecture Highlights&quot;">​</a></h2><ul><li><strong>Routing</strong>: Handled entirely via <code>react-router-dom</code>. Protected routes check the JWT context, redirecting unauthorized users back to <code>/login</code>.</li><li><strong>State Management</strong>: API interactions are heavily managed by <code>@tanstack/react-query</code>. Network requests cache responses and invalidate automatically (e.g., confirming a challan invalidates the <code>[&#39;products&#39;]</code> query key, updating inventory instantly across the app).</li><li><strong>Styling</strong>: Tailwind CSS is used exclusively for styling. Standardized UI components (Buttons, Modals, Badges) exist in <code>src/components/common</code>.</li><li><strong>Forms &amp; Validation</strong>: Input is captured via <code>react-hook-form</code> and synchronously validated on the client side using <code>zod</code> schemas matching the backend validations exactly.</li><li><strong>Service Layer</strong>: An Axios instance (<code>src/services/api.ts</code>) automatically injects the <code>Authorization</code> bearer token into headers and catches 401 Unauthorized errors to trigger global logouts.</li></ul>',4)])])}co